mapper.update:
update platform_pass_order
set status = 1, transaction_id = #{wxOrderId}, xpay_env = #{env}, paid_time = #{paidTime}
where id = #{id} and status in (0, 2) and channel = 'XPAY'

update platform_pass_order set status = 1, refund_no = null, refund_reason = null,
    refund_requested_by = null, refund_requested_time = null
where id = #{id} and status = 4 and refund_no = #{refundNo}

update platform_pass_order
set status = 3, refund_fact_id = #{factId}, refund_fact_hash = #{factHash}, refunded_time = #{refundedTime}
where id = #{id} and status = 4 and refund_no is not null

mapper.select:
select max(valid_to) from platform_pass_membership
where member_id = #{memberId} and status = 1 and valid_to > #{now}
for update

select max(m.valid_to) from platform_pass_membership m
join platform_pass_order o on o.id = m.order_id and o.status = 1
where m.member_id = #{memberId} and m.status = 1 and m.valid_to > #{now}

select t.id, t.name, t.img_url, t.product_type, t.total_time, t.location_count, t.address_name
from cms_topic t
where 
and t.product_type = #{productType}
order by t.id desc
limit #{limit}
